package com.oms.supplychain.service.wms;

import org.springframework.stereotype.Component;
import org.w3c.dom.Element;
import java.time.*;
import java.time.format.DateTimeFormatter;
import java.util.*;
import java.util.stream.Collectors;
import static com.oms.supplychain.service.wms.WmsStore.*;

/** Supplier-refused goods come back through an independent QTRK entryorder. */
@Component public class QimenReclaimProtocol {
 private String v(Element e,String key){Element n=QimenProtocol.child(e,key);return n==null?"":n.getTextContent().trim();}
 private long q(String raw){try{long n=new java.math.BigDecimal(raw).longValueExact();require(n>=0&&n<=100000000,"收回数量无效");return n;}catch(Exception e){throw new IllegalArgumentException("收回数量须为非负整数");}}
 public static boolean matches(String body){try{Element h=QimenProtocol.child(QimenProtocol.parse(body),"entryOrder");return h!=null&&QimenProtocol.child(h,"entryOrderCode")!=null&&QimenProtocol.child(h,"entryOrderCode").getTextContent().startsWith("CGH");}catch(Exception e){return false;}}
 public WmsProtocol.Wire request(Map<String,Object> connection,String secret,String action,Map<String,Object>d,Map<String,Object> route,List<Map<String,Object>> lines){
  require("QIMEN".equals(connection.get("provider"))&&"2.0".equals(connection.get("api_version")),"收回入库需要奇门2.0接口");String owner=QimenProtocol.tag("ownerCode",route.get("external_owner")),warehouse=QimenProtocol.tag("warehouseCode",route.get("external_warehouse")),sn=QimenProtocol.tag("entryOrderCode",d.get("reclaim_sn"));String body;
  if(action.equals("CREATE")){StringBuilder b=new StringBuilder("<request><entryOrder>");b.append(sn).append(owner).append(warehouse).append(QimenProtocol.tag("orderType","QTRK")).append(QimenProtocol.tag("totalOrderLines",lines.size())).append(QimenProtocol.tag("remark",d.get("reason"))).append(QimenProtocol.tag("logisticsCode",d.get("carrier_code"))).append(QimenProtocol.tag("expressCode",d.get("waybill"))).append("</entryOrder><orderLines>");for(Map<String,Object> l:lines)b.append("<orderLine>").append(QimenProtocol.tag("orderLineNo",l.get("id"))).append(QimenProtocol.tag("itemCode",l.get("sku_sn"))).append(QimenProtocol.tag("itemName",l.get("goods_name"))).append(owner).append(QimenProtocol.tag("batchCode",l.get("batch_code"))).append(QimenProtocol.tag("inventoryType","CP".equals(l.get("inventory_type"))?"CC":"ZP")).append(QimenProtocol.tag("planQty",l.get("quantity"))).append(QimenProtocol.tag("purchasePrice",l.get("purchase_price"))).append("</orderLine>");body=b.append("</orderLines></request>").toString();}
  else if(action.equals("CANCEL"))body="<request>"+QimenProtocol.tag("orderCode",d.get("reclaim_sn"))+QimenProtocol.tag("orderId",d.get("external_order"))+QimenProtocol.tag("orderType","QTRK")+owner+warehouse+QimenProtocol.tag("cancelReason",d.get("reason"))+"</request>";
  else body="<request>"+sn+QimenProtocol.tag("entryOrderId",d.get("external_order"))+owner+warehouse+QimenProtocol.tag("page",1)+QimenProtocol.tag("pageSize",100)+"</request>";
  Map<String,String> p=new TreeMap<>();p.put("app_key",text(connection.get("app_key")));p.put("customerId",text(connection.get("customer_id")));p.put("method","taobao.qimen."+(action.equals("CANCEL")?"order.cancel":"entryorder."+(action.equals("CREATE")?"create":"query")));p.put("v","2.0");p.put("format","xml");p.put("sign_method","md5");p.put("timestamp",LocalDateTime.now(ZoneId.of("Asia/Shanghai")).format(DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm:ss")));p.put("sign",QimenProtocol.sign(p,body,secret));return new WmsProtocol.Wire(text(connection.get("endpoint"))+"?"+p.entrySet().stream().map(e->QimenProtocol.enc(e.getKey())+"="+QimenProtocol.enc(e.getValue())).collect(Collectors.joining("&")),body,"application/xml;charset=UTF-8");
 }
 public WmsProtocol.Reply reply(String body){Element root=QimenProtocol.parse(body);require("response".equals(root.getTagName())&&Arrays.asList("success","failure").contains(v(root,"flag")),"仓库未返回明确入库结果");WmsProtocol.Reply r=new WmsProtocol.Reply();r.success="success".equals(v(root,"flag"));r.code=v(root,"code");r.message=v(root,"message");Element h=QimenProtocol.child(root,"entryOrder");if(h==null)h=root;r.externalOrder=v(h,"entryOrderId");r.documentSn=v(h,"entryOrderCode");r.owner=v(h,"ownerCode");r.warehouse=v(h,"warehouseCode");r.status=v(h,"status");return r;}
 public Map<String,Object> callback(Map<String,Object> connection,String secret,Map<String,String> params,String body){
  WmsProtocol.Receipt verified=new QimenProtocol().callback(connection,secret,params,body);Element root=QimenProtocol.parse(body),h=QimenProtocol.child(root,"entryOrder");String type=v(h,"entryOrderType");if(type.isEmpty())type=v(h,"orderType");require("QTRK".equals(type),"收回入库须回传QTRK类型");require(!verified.messageId.isEmpty()&&verified.messageId.length()<=128,"收回实收缺少原消息身份");Element container=QimenProtocol.child(root,"orderLines");require(container!=null,"收回实收缺少商品明细");List<Map<String,Object>> rows=new ArrayList<>();List<Element> original=QimenProtocol.children(container,"orderLine");require(!original.isEmpty()&&original.size()<=200&&(verified.totalLines==null||verified.totalLines==original.size()),"收回实收明细尚未完整，请补齐后回传");
  for(Element l:original){long key=id(v(l,"orderLineNo")),actual=q(v(l,"actualQty")),sum=0;Element group=QimenProtocol.child(l,"batchs");List<Element> batches=group==null?Collections.singletonList(l):QimenProtocol.children(group,"batch");require(!batches.isEmpty(),"收回批次明细为空");for(Element b:batches){long qty=q(v(b,"actualQty"));sum+=qty;String grade=v(b,"inventoryType");require(Arrays.asList("ZP","CC").contains(grade),"收回质量仅支持正品ZP或次品CC");rows.add(map("line_key",key,"sku_sn",v(l,"itemCode"),"batch_code",v(b,"batchCode"),"inventory_type",grade.equals("CC")?"CP":"ZP","quantity",qty,"owner_code",v(l,"ownerCode")));}require(sum==actual,"收回批次实收合计与原行不一致");}
  return map("reclaim_sn",verified.ticketSn,"external_order",verified.externalOrder,"owner_code",verified.owner,"warehouse_code",verified.warehouse,"message_id",verified.messageId,"complete",verified.complete,"status",verified.status,"lines",rows);
 }
}
